// ---------- v1.9: TRAPPOLE — formule mirate per i casi in cui si inciampa ----------
const TRAPS = {
  sogg_dopo: { s: ["log_sogg"], t: "il soggetto non sta sempre all'inizio",
    d: "Chiediti «chi?» o «che cosa?» davanti al verbo: «Nel bosco vivevano sette nani» → chi viveva? <b>sette nani</b>. Il soggetto può stare anche in fondo alla frase, e può essere perfino un verbo: «<b>Fumare</b> fa male»." },
  piacere: { s: ["log_sogg", "gr_pron"], t: "piacere, mancare, servire",
    d: "In «Mi piace <b>la musica</b>» chi piace? la musica: è lei il soggetto. «Mi», «a me», «a Luca» vogliono dire «a qualcuno»: non sono mai il soggetto. Prova: metti la cosa al plurale e il verbo cambia → mi piacci<b>ono</b> i film." },
  co_prep: { s: ["log_ogg"], t: "con la preposizione non è complemento oggetto",
    d: "Il complemento oggetto risponde a «chi?» o «che cosa?» <b>senza preposizione davanti</b>. «Va <b>a</b> scuola», «penso <b>a</b> te», «corre <b>al</b> parco»: c'è una preposizione → non è complemento oggetto. «<b>Ti</b> aspetto» invece sì: aspetto chi? te." },
  pron_lgl: { s: ["gr_pron"], t: "lo, gli o le?",
    d: "Cerca la «a». Senza «a» → <b>lo, la, li, le</b>: ho visto Marco → <b>l'</b>ho visto. Con «a» → <b>gli</b> per un maschio o per loro, <b>le</b> per una femmina: ho parlato a Marco → <b>gli</b> ho parlato; a Sara → <b>le</b> ho parlato." },
};
TRAPS.sce = { s: ["ort_cie"], t: "SCE o SCIE?",
  d: "La i dopo <b>sc</b> si scrive solo in poche parole da ricordare: <b>scienza, scienze, scienziato, coscienza</b>. Negli altri casi è <b>sce</b>: fini<b>sce</b>, cono<b>sce</b>, pe<b>sce</b>, <b>sce</b>na. E al futuro di mangiare, cominciare, lasciare, viaggiare la i sparisce: man<b>ge</b>rò, comin<b>ce</b>rà, la<b>sce</b>rai." };
TRAPS.comp = { s: ["ort_comp"], t: "una cosa sola o due parole?",
  d: "Chiediti: indica <b>un oggetto o una persona sola</b>, con un significato nuovo? Allora è una parola: il <b>portaombrelli</b>, la <b>cassaforte</b>, il <b>senzatetto</b>. Se invece una parola fa l'azione o descrive l'altra, restano staccate: Luca <b>porta l'ombrello</b>, una <b>cassa forte</b> (robusta), una casa <b>senza tetto</b>." };
const TRAP_OF = {};
[["sce", "cie33 cie34 cie35 cie36 cie38 cie41 cie42 cie43 cie44 cie45 cie47 cie48 cie49 cie50 cie51 cie52 cie53 cie54 cie55"], ["comp", "cp15 cp16 cp17 cp18 cp19 cp21 cp22 cp32 cp34"], ["sogg_dopo", "sg2 sg8 sg13 sg14 sg15 sg16 sg31"], ["piacere", "sg11 sg12 sg27 sg30 pr6 pr28"],
 ["co_prep", "co2 co15 co16 co22 co23 co24 co28 co30"],
 ["pron_lgl", "pr1 pr2 pr4 pr7 pr9 pr11 pr12 pr13 pr14 pr29 pr33 pr34 pr35 pr36"]]
